1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.OwnerEmailInvalidException;
10	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsMissingException;
11	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInvalidException;
12	import org.springframework.web.bind.annotation.RequestBody;
13	
14	/**
15	 * First step of {@code POST /api/owners} and the single step that binds the request body. Rejects a
16	 * body that is missing or blank in any required field (firstName, lastName, address, city, telephone)
17	 * with a 400 whose {@code errors} array lists the offending field names. A whitespace-only value is
18	 * treated as blank — the DTO's {@code @Size(min = 1)} alone would accept it — so this check, not bean
19	 * validation, is the authoritative implementation of the required-field rule.
20	 *
21	 * <p>The telephone is then converted to E.164 form (see {@link OwnerTelephone#toE164(String)}); a
22	 * value that cannot form a valid E.164 number is rejected with a 400 via
23	 * {@link OwnerTelephoneInvalidException}. The E.164 value is written back onto the body so it is what
24	 * gets stored and returned.
25	 *
26	 * <p>Email is optional. When absent (null) it is left untouched. When present it must be a
27	 * syntactically valid address; otherwise the create is rejected with a 400 via
28	 * {@link OwnerEmailInvalidException}. A valid email is lower-cased and written back onto the body so
29	 * the lower-cased value is what gets stored and returned. The validated body is republished for
30	 * {@link BuildOwner}.
31	 */
32	public class ValidateOwner {
33	
34	    /** Pragmatic syntactic check: non-empty local part, '@', non-empty domain containing a dot. */
35	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
36	
37	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
38	            throws OwnerFieldsMissingException, OwnerTelephoneInvalidException,
39	            OwnerEmailInvalidException {
40	        List<String> missing = new ArrayList<>();
41	        if (isBlank(request.getFirstName())) {
42	            missing.add("firstName");
43	        }
44	        if (isBlank(request.getLastName())) {
45	            missing.add("lastName");
46	        }
47	        if (isBlank(request.getAddress())) {
48	            missing.add("address");
49	        }
50	        if (isBlank(request.getCity())) {
51	            missing.add("city");
52	        }
53	        if (isBlank(request.getTelephone())) {
54	            missing.add("telephone");
55	        }
56	        if (!missing.isEmpty()) {
57	            throw new OwnerFieldsMissingException(missing);
58	        }
59	        String e164 = OwnerTelephone.toE164(request.getTelephone());
60	        if (e164 == null) {
61	            throw new OwnerTelephoneInvalidException(request.getTelephone());
62	        }
63	        request.setTelephone(e164);
64	
65	        String email = request.getEmail();
66	        if (email != null) {
67	            if (!EMAIL.matcher(email).matches()) {
68	                throw new OwnerEmailInvalidException(email);
69	            }
70	            request.setEmail(email.toLowerCase());
71	        }
72	
73	        validated.set(request);
74	    }
75	
76	    private static boolean isBlank(String value) {
77	        return value == null || value.isBlank();
78	    }
79	}
