1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.OwnerHouseholdDuplicateException;
10	
11	/**
12	 * Runs after {@link ValidateOwner} and before {@link BuildOwner}. Rejects the create with a 409 via
13	 * {@link OwnerHouseholdDuplicateException} when another owner already has the same lastName and the
14	 * same address. Both fields are compared case-insensitively with surrounding whitespace stripped and
15	 * internal whitespace runs collapsed to a single space.
16	 *
17	 * <p>The request may opt out of this rule by setting {@code sharesHousehold} true, which permits
18	 * creating a second owner at the same household (same name and address).
19	 */
20	public class CheckOwnerHouseholdUnique {
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws OwnerHouseholdDuplicateException {
24	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
25	            return; // opted in to sharing a household; skip the duplicate check
26	        }
27	        String lastName = normalize(request.getLastName());
28	        String address = normalize(request.getAddress());
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (lastName.equals(normalize(existing.getLastName()))
31	                    && address.equals(normalize(existing.getAddress()))) {
32	                throw new OwnerHouseholdDuplicateException(request.getLastName(), request.getAddress());
33	            }
34	        }
35	    }
36	
37	    /** Lower-cases and collapses whitespace so comparison ignores case and incidental spacing. */
38	    private static String normalize(String value) {
39	        if (value == null) {
40	            return "";
41	        }
42	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
43	    }
44	}
