1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneDuplicateException;
8	
9	/**
10	 * Runs after {@link ValidateOwner} (which has converted the telephone to E.164 and republished the
11	 * body) and before {@link BuildOwner}. Rejects the create with a 409 via
12	 * {@link OwnerTelephoneDuplicateException} when the E.164 telephone already belongs to any other
13	 * owner. Existing owners are compared on their telephone converted to E.164 the same way, so stored
14	 * values with incidental formatting still match.
15	 */
16	public class CheckOwnerTelephoneUnique {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws OwnerTelephoneDuplicateException {
20	        // ValidateOwner has already converted the request telephone to E.164; only stored owners need it.
21	        String telephone = request.getTelephone();
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (telephone.equals(OwnerTelephone.toE164(existing.getTelephone()))) {
24	                throw new OwnerTelephoneDuplicateException(telephone);
25	            }
26	        }
27	    }
28	}
