1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Runs after {@link BuildOwner} and before {@link SaveOwner} on {@code POST /api/owners}. Assigns the
9	 * new owner's {@code customerCode} formatted {@code <LAST3>-<NNNN>}, where LAST3 is the upper-cased
10	 * first three letters of the owner's lastName and NNNN is a global 4-digit zero-padded sequence equal
11	 * to one more than the current number of owners (e.g. {@code SMI-0007}). The owner is still unsaved, so
12	 * the count excludes it and the sequence advances by one per create.
13	 */
14	public class AssignCustomerCode {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String lastName = owner.getLastName();
18	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
19	        int sequence = ownerRepository.findAll().size() + 1;
20	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
21	    }
22	}
