3	/**
4	 * Thrown by {@link org.springframework.samples.petclinic.rest.function.owner.CheckOwnerHouseholdUnique}
5	 * when the owner being created has the same lastName and address (compared case-insensitively with
6	 * collapsed whitespace) as an existing owner and the request did not set {@code sharesHousehold} true.
7	 * Handled by {@link OwnerHouseholdDuplicateExceptionHandler}, which responds 409.
8	 */
9	public class OwnerHouseholdDuplicateException extends Exception {
10	
11	    private final String lastName;
12	
13	    private final String address;
14	
15	    public OwnerHouseholdDuplicateException(String lastName, String address) {
16	        super("An owner with the same last name and address already exists: " + lastName + ", " + address);
17	        this.lastName = lastName;
18	        this.address = address;
19	    }
20	
21	    public String getLastName() {
22	        return this.lastName;
23	    }
24	
25	    public String getAddress() {
26	        return this.address;
27	    }
28	}
