5	
6	import net.officefloor.plugin.section.clazz.Parameter;
7	import net.officefloor.web.ObjectResponse;
8	import org.springframework.http.HttpStatus;
9	import org.springframework.http.ResponseEntity;
10	
11	/**
12	 * Responds 409 with a JSON body whose {@code errors} array names {@code lastName} and {@code address}
13	 * when the owner being created shares a last name and address with an existing owner and the request
14	 * did not opt in via {@code sharesHousehold}.
15	 */
16	public class OwnerHouseholdDuplicateExceptionHandler {
17	
18	    public void handle(@Parameter OwnerHouseholdDuplicateException ex,
19	            ObjectResponse<ResponseEntity<Map<String, Object>>> response) {
20	        Map<String, Object> body = Map.of("errors", List.of("lastName", "address"));
21	        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(body));
22	    }
23	}
